/**
 * Standard Scenario Regression Library — 50 core scenarios.
 *
 * Naming convention: {STREET}-{POSITION}-{INDEX}
 *   Streets: PRE (preflop), FLP (flop), TRN (turn), RVR (river), EDG (edge)
 *   Positions: BTN, SB, BB, UTG, CO, HJ
 *
 * Assertion types:
 *   "never_fold"   — use with range-chart bots; assertNever("fold", 50 runs)
 *   "must_raise"   — use with range-chart bots; assertAction("raise")
 *   "rationality"  — use with personality bots; assertRationality(maxFoldPct%)
 *   "no_free_fold" — canCheck=true; assertNever("fold") — engine invariant
 *
 * Source of truth: any change to the strategy engine or Scenario Lab service
 * must keep all 50 of these scenarios passing.
 */

export interface StandardScenario {
  id: string;
  description: string;
  holeCards: [string, string];
  communityCards: string[];
  position: string;
  pot: number;
  toCall: number;
  minRaise: number;
  numberOfPlayers: number;
  assertion: "never_fold" | "must_raise" | "rationality" | "no_free_fold";
  /** Maximum fold% allowed (rationality assertion only) */
  maxFoldPct?: number;
  /**
   * Best hand name for post-flop scenarios (pokersolver format).
   * Required for strong-hand scenarios so the personality evaluator
   * classifies the hand correctly instead of defaulting to "high_card".
   * Values: "ONE_PAIR", "TWO_PAIR", "THREE_OF_A_KIND", "STRAIGHT", "FLUSH",
   *         "FULL_HOUSE", "FOUR_OF_A_KIND", "STRAIGHT_FLUSH", "ROYAL_FLUSH"
   */
  bestHandName?: string;
}

